from pathlib import Path
rows=[
('scholarship-01','교내 장학금 제출 서류','신청서와 재학증명서','교내 장학금 신청 시 장학금 신청서와 재학증명서를 제출합니다. 온라인 학생포털의 장학 메뉴에 PDF로 올립니다. 서류 누락 시 접수 기간 안에 보완해야 합니다.','장학금 신청 서류 준비 증명서'),
('scholarship-02','교내 장학금 신청 절차','온라인 신청과 심사','학생포털 → 장학 → 교내 장학 신청에서 유형을 선택하고 서류를 첨부한 뒤 최종 제출합니다. 접수 완료 상태를 확인합니다. 심사 결과는 학생포털 장학 내역에 공지합니다. 이 자료에는 신청 마감일과 지급액이 기재되어 있지 않습니다.','장학금 신청 절차 방법 결과 기간'),
('registration-01','수강신청 방법','신청 단계','학생포털 → 수업 → 수강신청에서 희망 과목을 검색하고 분반과 시간을 확인한 뒤 신청합니다. 시간표가 겹치면 신청할 수 없습니다. 신청 후 수강 목록을 다시 확인합니다.','수강신청 수업 과목 시간표'),
('registration-02','수강 정정 안내','변경과 확인','수강 정정 기간에는 학생포털에서 기존 과목을 취소하고 새 과목을 신청할 수 있습니다. 정원이 찬 과목은 학과 사무실에 문의합니다. 정정 기간의 구체적인 날짜는 이 자료에 없습니다.','수강 정정 변경 취소 정원'),
('leave-01','일반 휴학 신청','신청 순서와 서류','일반 휴학은 지도교수 상담 → 학생포털 학적 메뉴에서 휴학 신청 → 학과 승인 확인 순서로 진행합니다. 휴학 신청서가 필요합니다. 승인 전에는 휴학이 확정되지 않습니다.','휴학 신청 절차 서류 상담 승인'),
('leave-02','복학 신청 안내','복학과 수강신청','복학 예정자는 학생포털 → 학적 → 복학 신청에서 신청하고 승인 상태를 확인합니다. 승인 후 수강신청과 등록 절차를 진행합니다. 군 휴학 후 복학은 전역 확인 서류를 첨부합니다.','복학 신청 군휴학 전역 등록'),
('dormitory-01','기숙사 입사 신청','선발과 준비','생활관 홈페이지에서 입사 신청서를 작성하고 재학 상태와 연락처를 확인합니다. 선발 결과를 조회한 뒤 안내된 기한 내 생활관비를 납부합니다. 이 자료에는 선발 점수와 생활관비 금액이 없습니다.','기숙사 생활관 입사 신청 비용'),
('dormitory-02','기숙사 생활 수칙','시설 고장 신고','생활관 시설 고장은 생활관 포털의 시설 보수 신청에 동·호실과 증상을 기재하여 접수합니다. 화재 등 긴급 상황에는 즉시 대피하고 119에 신고합니다. 일반 문의는 생활관 행정실에서 받습니다.','기숙사 생활관 고장 시설 보수 수리'),
('library-01','도서관 대출 안내','대출 수와 기간','학부생은 학생증으로 일반 도서를 최대 5권까지 14일 동안 대출할 수 있습니다. 반납 예정일 전에 예약자가 없는 도서에 한해 1회 7일 연장할 수 있습니다. 전자도서의 이용 조건은 별도입니다.','도서관 책 도서 대출 반납 연장 기간 몇권'),
('library-02','도서관 열람실 안내','좌석 예약','도서관 앱에서 열람실과 좌석을 선택하여 예약하고 20분 안에 입실 인증을 합니다. 인증하지 않으면 예약이 취소됩니다. 이용을 마치면 앱에서 퇴실 처리합니다.','도서관 열람실 좌석 예약 입실 퇴실'),
('certificate-01','재학증명서 발급','온라인 발급','학생포털 → 증명서 발급 → 재학증명서에서 국문 또는 영문을 선택하고 발급합니다. 출력 전 이름과 학적 상태를 확인합니다. 수수료 정보는 이 자료에 없습니다.','재학 증명서 발급 출력 영문 국문'),
('certificate-02','성적증명서 발급','학기 성적 확인','성적증명서는 학생포털 증명서 발급 메뉴에서 신청합니다. 해당 학기 성적이 확정된 후 반영됩니다. 성적 정정은 담당 교과목 교수에게 먼저 문의합니다.','성적 증명서 발급 학점 정정'),
('tuition-01','등록금 고지서 확인','고지서와 납부 확인','학생포털 → 등록 → 등록금 고지서에서 금액과 가상계좌를 확인합니다. 납부 후 포털의 납부 확인 메뉴에서 반영 여부를 확인합니다. 실제 계좌번호와 납부일은 이 자료에 포함하지 않습니다.','등록금 납부 고지서 계좌 확인'),
('tuition-02','등록금 분할 납부','신청과 유의사항','등록금 분할 납부는 학생포털 등록 메뉴에서 별도로 신청하며 승인 여부를 확인해야 합니다. 각 차수 납부기한을 지켜야 합니다. 차수별 금액과 정확한 기한은 개별 고지서를 확인합니다.','등록금 분납 분할 납부 신청'),
('counseling-01','학생 상담 예약','예약 절차','학생상담센터 홈페이지에서 상담 유형을 선택하고 가능한 시간을 예약합니다. 초기 면담 후 후속 상담을 정합니다. 예약 변경이나 취소는 상담센터에 미리 알립니다.','상담 심리 학생상담 예약 취소'),
('career-01','진로 취업 상담','진로 상담 신청','취업지원센터 포털에서 진로 상담을 예약하고 관심 분야와 상담 주제를 적습니다. 이력서 상담을 원하면 초안을 준비합니다. 상담은 취업 합격을 보장하지 않습니다.','진로 취업 이력서 상담 예약'),
('wifi-01','캠퍼스 Wi-Fi 연결','접속과 문제 해결','교내 무선망 Hanbit-Campus를 선택하고 학생포털 계정으로 인증합니다. 인증 오류가 나면 계정 상태와 비밀번호를 확인하고 기존 네트워크를 삭제한 뒤 재연결합니다. 해결되지 않으면 정보지원팀에 문의합니다.','와이파이 wifi 인터넷 무선망 연결 오류 비밀번호'),
('club-01','중앙 동아리 가입','가입 문의','학생회 동아리 안내에서 활동 내용을 확인하고 각 동아리 모집 공지의 가입 방법을 따릅니다. 모집 기간과 회비는 동아리마다 다릅니다. 이 자료에는 특정 동아리의 회비가 없습니다.','동아리 가입 모집 회비 활동'),
('meal-01','학생식당 이용','메뉴 확인','학생식당 주간 메뉴와 운영 시간은 학생복지 포털 식당 안내에서 확인합니다. 공휴일 운영 여부는 별도 공지를 확인합니다. 이 자료에는 오늘의 메뉴나 식사 가격이 없습니다.','학식 학생식당 식사 메뉴 운영 시간 가격'),
('lost-01','분실물 신고와 조회','분실물 처리','습득물은 학생지원팀 분실물 창구에 맡깁니다. 분실자는 학생포털 분실물 게시판에서 물품 특징과 습득 장소를 확인하고 본인 물품임을 확인할 자료를 지참해 방문합니다.','분실물 잃어버린 지갑 학생증 습득물 신고')]
out=Path(__file__).parent/'documents';out.mkdir(exist_ok=True)
manifest=[]; chunks=[]
for id,title,section,text,keywords in rows:
 doc={'id':id,'title':title,'section':section,'text':text,'keywords':keywords,'department':'가상 한빛대학교 학생지원','effective_date':'2026-11-26','version':'1.0','fictional':True,'source_key':f'documents/{id}.txt'}
 content=f'[과제용 가상 자료 · 실제 대학 규정 아님]\n한빛대학교 | {title}\n문서 ID: {id}\n절: {section}\n시행일: 2026-11-26\n\n{text}\n'
 (out/f'{id}.txt').write_text(content)
 manifest.append({k:v for k,v in doc.items() if k not in ['text','keywords']}); chunks.append(doc)
(out/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
(Path(__file__).parent/'corpus.json').write_text(json.dumps(chunks,ensure_ascii=False,indent=2))
